// Generated by scripts/generate-phone-contract.ts from src/shared/cards.ts, src/shared/risk.ts, src/shared/taskBrowser.ts,
// src/renderer/src/app/closeQuestionWords.ts, src/renderer/src/design/cards/cardSizeWords.ts and src/renderer/src/cards/
// (requiredActionsWords.ts, threadWords.ts, answersLine.ts, revisedLine.ts).
enum PhoneCardWords {
    static let replyHint = "anything to add?"
    static let anythingElse = "anything_else"
    static let sentWithChoice = "Sent with your choice:"
    static let reviewFinding = "Review finding"
    static let putAside = "Put aside"
    static let putAsideRest = "Put aside · back when it changes"
    static let maximize = "Maximize card"
    static let restore = "Restore card"
    static let closeQuestionTitle = "Close this card?"
    static let keepAnswering = "Keep answering"
    static let discardAndClose = "Discard and close"
    static let putAsideInstead = "Put aside instead"
    static let closeAnyway = "Close anyway"
    static let requiredActionsLead = "After merging, you need to…"
    static let threadWho = ["captain": "you", "crewmate": "crew", "firstmate": "mate", "host": "app"]
    static let threadWorking = "working"
    static let threadCard = "Card"
    static let threadCardUpdated = "updated"
    static let driverWords = ["crewmate": "the crewmate is driving", "nobody": "nobody is driving", "waiting": "paused for your help", "taking": "you are taking control", "captain": "you have control"]
    static let stopLineWords = ["captain": "you stopped it", "crewmate": "the crewmate closed it", "idle": "stopped after 30 minutes unused", "gone": "its page stopped working", "task-closed": "stopped when the task closed"]
    static let staleBrowser = "this card's browser has stopped"

    static func requiredActionsCount(_ count: Int) -> String { "\(count) required actions" }
    static func settingsCount(_ count: Int) -> String {
        count == 1 ? "settings · 1 value" : "settings · \(count) values"
    }
    static func messageCount(_ count: Int) -> String {
        count == 1 ? "1 message" : "\(count) messages"
    }
    static func newCount(_ count: Int) -> String { "\(count) new" }
    static func threadCount(_ count: Int) -> String { "thread · \(count)" }
    /** Who really wrote a thread line, and whether it came after the card closed ("Shared cards"). */
    static func contributor(host: Bool, label: String?, clarification: Bool) -> String {
        switch (host, label, clarification) {
        case (true, let label?, false): "Revised by \(label)"
        case (true, let label?, true): "Revised by \(label), after the card closed"
        case (false, let label?, false): "Written by \(label)"
        case (false, let label?, true): "Written by \(label), after the card closed"
        case (_, nil, true): "Written after the card closed"
        default: ""
        }
    }
    static func closeRest(_ key: String?) -> String {
        guard let key else { return "Close · stays readable in Tasks" }
        return "Close · stays on \(key)'s record"
    }
    static func closeQuestion(count: Int, preview: Bool, wrote: Bool) -> String {
        switch (min(count, 2) == 2 ? -1 : count, preview, wrote) {
        case (0, false, false): "You picked 0 answers. Closing will discard them."
        case (0, false, true): "You wrote a reply. Closing will discard it."
        case (0, true, false): "You changed 0 settings. Closing will discard them."
        case (0, true, true): "You wrote a reply. Closing will discard it."
        case (1, false, false): "You picked 1 answer. Closing will discard it."
        case (1, false, true): "You picked 1 answer and wrote a reply. Closing will discard them."
        case (1, true, false): "You changed 1 setting. Closing will discard it."
        case (1, true, true): "You changed 1 setting and wrote a reply. Closing will discard them."
        case (-1, false, false): "You picked \(count) answers. Closing will discard them."
        case (-1, false, true): "You picked \(count) answers and wrote a reply. Closing will discard them."
        case (-1, true, false): "You changed \(count) settings. Closing will discard them."
        case (-1, true, true): "You changed \(count) settings and wrote a reply. Closing will discard them."
        default: ""
        }
    }
    /** `author` as the Mac names it: "your first mate" or the crewmate. */
    static func unansweredReply(author: String, key: String?) -> String {
        let who = author.prefix(1).uppercased() + author.dropFirst()
        guard let key else { return "\(who) has not answered your reply yet. Closed, its answer stays readable in Tasks." }
        return "\(who) has not answered your reply yet. Closed, its answer stays on \(key)'s record."
    }
    static func answersLine(answered: Int, of: Int, changed: Int, preview: Bool) -> String {
        switch (preview, changed > 0) {
        case (false, false): "\(answered) of \(of) picked"
        case (false, true): "\(answered) of \(of) picked · \(changed) changed"
        case (true, false): "\(answered) of \(of) answered"
        case (true, true): "\(answered) of \(of) answered · \(changed) changed"
        }
    }
    /** `time` is the time of day, with the date in front when it was not today, as the Mac's clock writes it. */
    static func revisedLine(time: String, added: Int, removed: Int, rewritten: Bool) -> String {
        if rewritten { return "Rewritten \(time)" }
        return switch (min(added, 2) == 2 ? -1 : added, min(removed, 2) == 2 ? -1 : removed) {
        case (0, 0): "Revised \(time)"
        case (0, 1): "Revised \(time) · 1 part removed"
        case (0, -1): "Revised \(time) · \(removed) parts removed"
        case (1, 0): "Revised \(time) · 1 part new"
        case (1, 1): "Revised \(time) · 1 part new · 1 removed"
        case (1, -1): "Revised \(time) · 1 part new · \(removed) removed"
        case (-1, 0): "Revised \(time) · \(added) parts new"
        case (-1, 1): "Revised \(time) · \(added) parts new · 1 removed"
        case (-1, -1): "Revised \(time) · \(added) parts new · \(removed) removed"
        default: ""
        }
    }

    struct Dimension { let id: String; let label: String; let levels: [String: String] }
    /** The seven dimensions in the Mac's order, each with its name and what each level means. */
    static let riskDimensions: [Dimension] = [
        Dimension(id: "blast", label: "Blast radius", levels: ["low": "narrow: one area", "medium": "some: a few areas", "high": "wide: shared code or many areas"]),
        Dimension(id: "behavior", label: "Behavior", levels: ["low": "nothing, or a defect corrected", "medium": "adds something a person opts into", "high": "changes what happens by default"]),
        Dimension(id: "undo", label: "Undo", levels: ["low": "revert and done", "medium": "needs a step: saved data or settings moved", "high": "hard: data rewritten, released or sent outside"]),
        Dimension(id: "evidence", label: "Evidence", levels: ["low": "shown working end to end", "medium": "tests only", "high": "not shown"]),
        Dimension(id: "sensitivity", label: "Sensitivity", levels: ["low": "none", "medium": "saved data or settings", "high": "sign-ins, keys, payments or a release"]),
        Dimension(id: "novelty", label: "Novelty", levels: ["low": "edits well-trodden code", "medium": "new code beside existing", "high": "a new subsystem"]),
        Dimension(id: "deps", label: "Dependencies", levels: ["low": "none", "medium": "updates a package", "high": "adds a package"]),
    ]
    /** A level's color, in the checks' language. */
    static let riskTone: [String: String] = ["low": "ok", "medium": "warn", "high": "danger"]
}

